/*
 * Return the value of an INFO key from a semicolon-separated VCF INFO
 * field.  *value_len is set to the length of the value, excluding any
 * following semicolon.  Returns NULL if the key is not present.
 */
static const char *vcf_find_info_value(const char *info, const char *key,
                                       size_t *value_len)
{
    size_t key_len = strlen(key);
    const char *p = info;

    while (*p) {
        const char *end = strchr(p, ';');
        size_t field_len = end ? (size_t)(end - p) : strlen(p);

        if (field_len >= key_len + 1
            && memcmp(p, key, key_len) == 0
            && p[key_len] == '=') {
            *value_len = field_len - key_len - 1;
            return p + key_len + 1;
        }

        if (!end) break;
        p = end + 1;
    }

    return NULL;
}

/*
 * Does this VCF ALT allele describe a symbolic structural variant whose
 * reference span is given by INFO/SVLEN (i.e. <DEL>, <DUP>, <INV> or
 * <CNV>, optionally with a subtype suffix after a colon)?
 */
static int vcf_alt_spans_reference(const char *alt, size_t len)
{
    const char *base_end, *colon, *p;
    size_t base_len;

    if (len < 5 || alt[0] != '<' || alt[len - 1] != '>') return 0;

    base_end = alt + len - 1;
    colon = memchr(alt + 1, ':', base_end - (alt + 1));
    if (colon) base_end = colon;

    p = alt + 1;
    base_len = base_end - p;
    if (base_len != 3) return 0;

    if (toupper_c(p[0]) == 'D' && toupper_c(p[1]) == 'E'
        && toupper_c(p[2]) == 'L') return 1;
    if (toupper_c(p[0]) == 'D' && toupper_c(p[1]) == 'U'
        && toupper_c(p[2]) == 'P') return 1;
    if (toupper_c(p[0]) == 'I' && toupper_c(p[1]) == 'N'
        && toupper_c(p[2]) == 'V') return 1;
    if (toupper_c(p[0]) == 'C' && toupper_c(p[1]) == 'N'
        && toupper_c(p[2]) == 'V') return 1;

    return 0;
}

int tbx_parse1(const tbx_conf_t *conf, size_t len, char *line, tbx_intv_t *intv)
{
    size_t i, b = 0;
    int id = 1;
    char *s;
    const char *alt_field = NULL;
    size_t alt_field_len = 0;
    intv->ss = intv->se = 0; intv->beg = intv->end = -1;
    for (i = 0; i <= len; ++i) {
        if (line[i] == '\t' || line[i] == 0) {
            if (id == conf->sc) {
                intv->ss = line + b; intv->se = line + i;
            } else if (id == conf->bc) {
                // here ->beg is 0-based.
                if ((conf->preset&0xffff) == TBX_GAF){
                    // if gaf find the smallest and largest node id
                    char *t;
                    int64_t nodeid = -1;
                    for (s = line + b + 1; s < line + i;) {
                        nodeid = strtoll(s, &t, 0);
                        if(intv->beg == -1){
                            intv->beg = intv->end = nodeid;
                        } else {
                            if(nodeid < intv->beg){
                                intv->beg = nodeid;
                            }

                            if(nodeid > intv->end){
                                intv->end = nodeid;
                            }
                        }
                        s = t + 1;
                    }
                } else {
                    intv->beg = strtoll(line + b, &s, 0);

                    if (conf->bc <= conf->ec) // don't overwrite an already set end point
                        intv->end = intv->beg;

                    if ( s==line+b ) return -1; // expected int

                    if (!(conf->preset&TBX_UCSC))
                        --intv->beg;
                    else if (conf->bc <= conf->ec)
                        ++intv->end;

                    if (intv->beg < 0) {
                        hts_log_warning("Coordinate <= 0 detected. "
                                        "Did you forget to use the -0 option?");
                        intv->beg = 0;
                    }
                    if (intv->end < 1) intv->end = 1;
                }
            } else {
                if ((conf->preset&0xffff) == TBX_GENERIC) {
                    if (id == conf->ec)
                    {
                        intv->end = strtoll(line + b, &s, 0);
                        if ( s==line+b ) return -1; // expected int
                    }
                } else if ((conf->preset&0xffff) == TBX_SAM) {
                    if (id == 6) { // CIGAR
                        int l = 0;
                        char *t;
                        for (s = line + b; s < line + i;) {
                            long x = strtol(s, &t, 10);
                            char op = toupper_c(*t);
                            if (op == 'M' || op == 'D' || op == 'N') l += x;
                            s = t + 1;
                        }
                        if (l == 0) l = 1;
                        intv->end = intv->beg + l;
                    }
                } else if ((conf->preset&0xffff) == TBX_VCF) {
                    if (id == 4) {
                        if (b < i) intv->end = intv->beg + (i - b);
                    } else if (id == 5) {
                        // Remember the ALT field, as it may be needed when
                        // the INFO field is parsed below.
                        alt_field = line + b;
                        alt_field_len = i - b;
                    } else if (id == 8) {
                        const char *val;
                        size_t val_len;
                        int end_set = 0;
                        int c = line[i];
                        line[i] = 0;

                        // Explicit INFO/END takes precedence.  If it is
                        // absent (or invalid), the VCF specification says the
                        // end of a symbolic structural variant must be
                        // computed from INFO/SVLEN.
                        val = vcf_find_info_value(line + b, "END", &val_len);
                        if (val && val_len > 0 && *val != '.') {
                            long long end = strtoll(val, &s, 0);
                            if (s != val) {
                                if (end <= intv->beg) {
                                    static int reported = 0;
                                    if (!reported) {
                                        int l = intv->ss ? (int) (intv->se - intv->ss) : 0;
                                        hts_log_warning("VCF INFO/END=%lld is smaller than POS at %.*s:%"PRIhts_pos"\n"
                                                        "This tag will be ignored. "
                                                        "Note: only one invalid END tag will be reported.",
                                                        end, l >= 0 ? l : 0,

                                                        end, l >= 0 ? l : 0,
                                                        intv->ss ? intv->ss : "",
                                                        intv->beg);
                                        reported = 1;
                                    }
                                } else {
                                    intv->end = end;
                                    end_set = 1;
                                }
                            }
                        }

                        if (!end_set && alt_field) {
                            val = vcf_find_info_value(line + b, "SVLEN", &val_len);
                            if (val) {
                                const char *ap = alt_field;
                                const char *alt_end = alt_field + alt_field_len;
                                const char *sp = val;
                                const char *svlen_end = val + val_len;

                                while (ap < alt_end) {
                                    const char *a_next = memchr(ap, ',', alt_end - ap);
                                    size_t a_len = a_next
                                        ? (size_t)(a_next - ap)
                                        : (size_t)(alt_end - ap);

                                    if (sp < svlen_end) {
                                        const char *s_next = memchr(sp, ',', svlen_end - sp);
                                        size_t s_len = s_next
                                            ? (size_t)(s_next - sp)
                                            : (size_t)(svlen_end - sp);

                                        if (vcf_alt_spans_reference(ap, a_len)
                                            && s_len > 0 && *sp != '.') {
                                            long long svlen = strtoll(sp, &s, 0);
                                            if (s == sp + s_len) {
                                                if (svlen < 0) svlen = -svlen;
                                                if (svlen > 0) {
                                                    int64_t end = (int64_t) intv->beg + 1 + svlen;
                                                    if (end > intv->end)
                                                        intv->end = end;
                                                }
                                            }
                                        }

                                        sp = s_next ? s_next + 1 : svlen_end;
                                    }

                                    ap = a_next ? a_next + 1 : alt_end;
                                }
                            }
                        }

                        line[i] = c;
                    }
                }
            }
            b = i + 1;
            ++id;
        }
    }
    if (intv->ss == 0 || intv->se == 0 || intv->beg < 0 || intv->end < 0) return -1;
    return 0;
}

static inline int get_intv(tbx_t *tbx, kstring_t *str, tbx_intv_t *intv, int is_add)
{
    if (tbx_parse1(&tbx->conf, str->l, str->s, intv) == 0) {
        int c = *intv->se;
        *intv->se = '\0';
        if ((tbx->conf.preset&0xffff) == TBX_GAF){
            intv->tid = 0;
        } else {
            intv->tid = get_tid(tbx, intv->ss, is_add);
        }
        *intv->se = c;
        if (intv->tid < 0) return -2;  // get_tid out of memory
        return (intv->beg >= 0 && intv->end >= 0)? 0 : -1;
    } else {
        char *type = NULL;
        switch (tbx->conf.preset&0xffff)
        {
            case TBX_SAM: type = "TBX_SAM"; break;
            case TBX_VCF: type = "TBX_VCF"; break;
            case TBX_GAF: type = "TBX_GAF"; break;
            case TBX_UCSC: type = "TBX_UCSC"; break;
            default: type = "TBX_GENERIC"; break;
        }
        if (hts_is_utf16_text(str))
            hts_log_error("Failed to parse %s: offending line appears to be encoded as UTF-16", type);
        else
            hts_log_error("Failed to parse %s: was wrong -p [type] used?\nThe offending line was: \"%s\"",
                type, str->s);
        return -1;
    }
}

